```

---

### C++
**Option 1: Using Standard Library**
```cpp
#include <iostream>
#include <algorithm> // for *max_element
#include <vector>

int main() {
    std::vector<int> arr = {10, 324, 45, 90, 9808};
    int maxVal = *std::max_element(arr.begin(), arr.end());
    std::cout << maxVal;
    return 0;
}
